import{a as e,i as t,r as n,t as r}from"./app-DbTmPHyY.js";var i=JSON.parse(`{"path":"/%E7%AC%AC02%E7%AB%A0%20%E4%BF%A1%E6%81%AF%E6%8A%80%E6%9C%AF%E5%8F%91%E5%B1%95/2.1%20%E4%BF%A1%E6%81%AF%E6%8A%80%E6%9C%AF%E6%A6%82%E8%BF%B0.html","title":"2.1 信息技术概述","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第02章 信息技术发展/2.1 信息技术概述.md"}`),a={name:`2.1 信息技术概述.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_2-1-信息技术概述" tabindex="-1"><a class="header-anchor" href="#_2-1-信息技术概述"><span>2.1 信息技术概述</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>信息技术（Information Technology，IT）是指用于管理和处理信息所采用的各种技术的总称，主要包括计算机技术、通信技术、网络技术等。</p><h2 id="发展历程" tabindex="-1"><a class="header-anchor" href="#发展历程"><span>发展历程</span></a></h2><h3 id="第一代-电子管计算机-1946-1958" tabindex="-1"><a class="header-anchor" href="#第一代-电子管计算机-1946-1958"><span>第一代：电子管计算机（1946-1958）</span></a></h3><ul><li>主要特征：使用电子管作为逻辑元件</li><li>体积庞大、功耗高、可靠性差</li><li>代表：ENIAC</li></ul><h3 id="第二代-晶体管计算机-1959-1964" tabindex="-1"><a class="header-anchor" href="#第二代-晶体管计算机-1959-1964"><span>第二代：晶体管计算机（1959-1964）</span></a></h3><ul><li>主要特征：使用晶体管作为逻辑元件</li><li>体积减小、功耗降低、性能提升</li><li>开始出现操作系统</li></ul><h3 id="第三代-集成电路计算机-1965-1970" tabindex="-1"><a class="header-anchor" href="#第三代-集成电路计算机-1965-1970"><span>第三代：集成电路计算机（1965-1970）</span></a></h3><ul><li>主要特征：使用集成电路（IC）</li><li>体积进一步缩小、性能大幅提升</li><li>出现分时操作系统</li></ul><h3 id="第四代-大规模集成电路计算机-1971-至今" tabindex="-1"><a class="header-anchor" href="#第四代-大规模集成电路计算机-1971-至今"><span>第四代：大规模集成电路计算机（1971-至今）</span></a></h3><ul><li>主要特征：使用大规模和超大规模集成电路</li><li>微型计算机普及</li><li>互联网技术发展</li></ul><h3 id="第五代-人工智能计算机-正在发展" tabindex="-1"><a class="header-anchor" href="#第五代-人工智能计算机-正在发展"><span>第五代：人工智能计算机（正在发展）</span></a></h3><ul><li>主要特征：智能化、网络化</li><li>人工智能、机器学习广泛应用</li><li>量子计算、脑科学等新兴技术</li></ul><h2 id="核心技术" tabindex="-1"><a class="header-anchor" href="#核心技术"><span>核心技术</span></a></h2><h3 id="计算机技术" tabindex="-1"><a class="header-anchor" href="#计算机技术"><span>计算机技术</span></a></h3><ul><li>硬件技术：CPU、内存、存储设备</li><li>软件技术：操作系统、编程语言、数据库</li></ul><h3 id="通信技术" tabindex="-1"><a class="header-anchor" href="#通信技术"><span>通信技术</span></a></h3><ul><li>有线通信：光纤、双绞线</li><li>无线通信：5G、Wi-Fi、蓝牙</li></ul><h3 id="网络技术" tabindex="-1"><a class="header-anchor" href="#网络技术"><span>网络技术</span></a></h3><ul><li>局域网（LAN）</li><li>广域网（WAN）</li><li>互联网（Internet）</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>信息技术发展的五个阶段</strong></li><li><strong>各阶段的主要特征和代表技术</strong></li><li><strong>信息技术的核心组成部分</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>电子管，晶体管，集成大集人工智能，五代发展不停歇</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：以下哪项不是信息技术发展阶段的划分依据？ A. 逻辑元件 B. 存储容量 C. 运算速度 D. 软件类型</p><p><strong>答案</strong>：D</p><p><strong>解析</strong>：信息技术发展阶段主要根据逻辑元件的演变来划分，包括电子管、晶体管、集成电路、大规模集成电路和人工智能。软件类型不是划分依据。</p>`,29)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};